from pathlib import Path
p=Path('src/isomedia/box_code_meta.c')
text=p.read_text()
old='''GF_Err bxml_box_read(GF_Box *s, GF_BitStream *bs)
{
	GF_BinaryXMLBox *ptr = (GF_BinaryXMLBox *)s;

	ptr->data_length = (u32)(ptr->size);
	ptr->data = (char*)gf_malloc(sizeof(char)*ptr->data_length);
	if (!ptr->data) return GF_OUT_OF_MEM;
	gf_bs_read_data(bs, ptr->data, ptr->data_length);
	return GF_OK;
}
'''
new='''GF_Err bxml_box_read(GF_Box *s, GF_BitStream *bs)
{
	GF_BinaryXMLBox *ptr = (GF_BinaryXMLBox *)s;

	if (ptr->size > gf_bs_available(bs)) return GF_ISOM_INCOMPLETE_FILE;
	ptr->data_length = (u32)(ptr->size);
	ptr->data = (char*)gf_malloc(sizeof(char)*ptr->data_length);
	if (!ptr->data) return GF_OUT_OF_MEM;
	gf_bs_read_data(bs, ptr->data, ptr->data_length);
	return GF_OK;
}
'''
p.write_text(text.replace(old,new))
PY
sed -n '206,216p' src/isomedia/box_code_meta.c && echo '--- build? ---' && bash ./build.sh >/tmp/build.log 2>&1; tail -20 /tmp/build.log

